package ru.meguboom.mobile;
import org.junit.Test;import static org.junit.Assert.*;import java.io.*;import java.nio.file.*;
public class OfflineAudioTest {
 final OfflineAudio.State normal=new OfflineAudio.State(){public boolean cancelled(){return false;}public void progress(long b,long e){}};
 @Test public void publishesOnlyCompletedCopy()throws Exception{File dir=Files.createTempDirectory("audio-copy").toFile(),temp=new File(dir,"part"),target=new File(dir,"audio");OfflineAudio.copy(new ByteArrayInputStream(new byte[]{1,2,3}),temp,target,3,normal);assertFalse(temp.exists());assertArrayEquals(new byte[]{1,2,3},Files.readAllBytes(target.toPath()));target.delete();dir.delete();}
 @Test public void truncatedResponseIsNeverPublished()throws Exception{File dir=Files.createTempDirectory("audio-short").toFile(),temp=new File(dir,"part"),target=new File(dir,"audio");try{OfflineAudio.copy(new ByteArrayInputStream(new byte[]{1}),temp,target,8,normal);fail();}catch(IOException expected){}assertFalse(target.exists());assertFalse(temp.exists());dir.delete();}
 @Test public void cancellationCleansTemporaryFile()throws Exception{File dir=Files.createTempDirectory("audio-cancel").toFile(),temp=new File(dir,"part"),target=new File(dir,"audio");try{OfflineAudio.copy(new ByteArrayInputStream(new byte[]{1}),temp,target,1,new OfflineAudio.State(){public boolean cancelled(){return true;}public void progress(long b,long e){}});fail();}catch(IOException expected){}assertFalse(target.exists());assertFalse(temp.exists());dir.delete();}
 @Test public void existingDownloadIsNotOverwritten()throws Exception{File dir=Files.createTempDirectory("audio-existing").toFile(),temp=new File(dir,"part"),target=new File(dir,"audio");Files.write(target.toPath(),new byte[]{9});try{OfflineAudio.copy(new ByteArrayInputStream(new byte[]{1}),temp,target,1,normal);fail();}catch(IOException expected){}assertArrayEquals(new byte[]{9},Files.readAllBytes(target.toPath()));assertFalse(temp.exists());target.delete();dir.delete();}
 @Test public void legacyOrphanIsPreservedWhenChoosingNewDownloadTarget()throws Exception{File dir=Files.createTempDirectory("audio-legacy").toFile(),old=new File(dir,"download.audio");Files.write(old.toPath(),new byte[]{9});File next=OfflineAudio.availableTarget(old);assertNotEquals(old,next);assertFalse(next.exists());assertArrayEquals(new byte[]{9},Files.readAllBytes(old.toPath()));old.delete();dir.delete();}
}
